(()=>{const root=document.documentElement;let theme;try{theme=localStorage.getItem('ml-theme')}catch(e){}root.dataset.theme=theme==='dark'||theme==='light'?theme:(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');document.addEventListener('DOMContentLoaded',()=>{const lang=root.lang, labels=lang==='ru'?['Тёмный режим','Светлый режим','На весь экран','Выйти из полного экрана']:lang==='en'?['Dark mode','Light mode','Full screen','Exit full screen']:['Қараңғы режим','Жарық режим','Толық экран','Толық экраннан шығу'];const controls=document.createElement('div');controls.className='view-controls';const toggle=document.createElement('button'),full=document.createElement('button');toggle.type=full.type='button';controls.append(toggle,full);(document.querySelector('.header-inner')||document.querySelector('.topbar')).append(controls);function sync(){const dark=root.dataset.theme==='dark';toggle.textContent=dark?'☀':'☾';toggle.title=toggle.ariaLabel=labels[dark?1:0];toggle.setAttribute('aria-pressed',String(dark));full.textContent=document.fullscreenElement?'⤢':'⛶';full.title=full.ariaLabel=labels[document.fullscreenElement?3:2];full.setAttribute('aria-pressed',String(!!document.fullscreenElement));document.querySelector('meta[name="theme-color"]').content=dark?'#101d19':'#f4f5ef'}toggle.onclick=()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('ml-theme',root.dataset.theme)}catch(e){}sync()};full.hidden=!document.fullscreenEnabled;full.onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await root.requestFullscreen()}catch(e){full.title=lang==='kk'?'Толық экран үшін F11 басыңыз':lang==='ru'?'Нажмите F11 для полного экрана':'Press F11 for full screen';let notice=document.querySelector('.view-notice');if(!notice){notice=document.createElement('div');notice.className='view-notice';notice.setAttribute('role','status');document.body.append(notice)}notice.textContent=full.title;setTimeout(()=>notice.remove(),5000)}};document.addEventListener('fullscreenchange',sync);sync()})})();